-- ============================================================
-- KOMS — Database Schema
-- Generated by scaffold-schema on 2026-07-12
-- Source: PRD.md confirmed 2026-07-12
-- Every table traces to a screen in PRD.md's Screen Inventory.
-- ============================================================

-- ============================================================
-- ROOT ENTITY
-- ============================================================
-- Multi-tenant root. 1 row seeded for v1 (Gio's center, Indonesia).
-- Exists now so Singapore/other-country expansion never requires a schema rebuild.
create table centers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  country text not null default 'Indonesia', -- 'Indonesia' | 'Singapore' | others as Kodecoon expands
  created_at timestamptz default now()
);

-- ============================================================
-- BUILD NOW — MVP (all P0, per the locked PRD)
-- ============================================================

-- Staff (teacher/center_manager/admin) AND parent accounts share this table.
-- id = auth.uid(), mirrors Supabase auth.users. Role-based, RLS-ready from day one
-- (same pattern as TCS Coffee's customer/admin/POS roles).
create table users (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique,
  name text not null,
  role text not null default 'teacher', -- 'teacher' | 'center_manager' | 'admin' | 'parent'
  center_id uuid references centers(id), -- null for parents, required for staff
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  -- Enforced, not just documented: several RLS policies scope by
  -- "center_id in (select center_id from users where id = auth.uid())".
  -- A parent with a non-null center_id would silently widen those policies to
  -- every student in the center, so the invariant has to be a constraint.
  constraint users_parent_has_no_center
    check (role <> 'parent' or center_id is null)
);

create table classes (
  id uuid primary key default gen_random_uuid(),
  center_id uuid not null references centers(id),
  teacher_id uuid not null references users(id),
  name text not null,           -- e.g. 'Scratch Junior', 'RCB', 'RGD Lv 2'
  age_bracket text,             -- e.g. '5-8', '8-12', '13-19'
  -- total lesson count is derived from COUNT(lessons) where class_id = this class,
  -- not stored here — avoids two sources of truth for curriculum size
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table students (
  id uuid primary key default gen_random_uuid(),
  center_id uuid not null references centers(id),
  name text not null,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table enrollments (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  class_id uuid not null references classes(id) on delete cascade,
  enrolled_date date not null default current_date,
  created_at timestamptz default now(),
  unique (student_id, class_id)
);

create table sessions (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references classes(id),
  teacher_id uuid not null references users(id),
  session_date date not null,
  session_time time,            -- nullable; used by My Schedule
  status text not null default 'scheduled', -- 'scheduled' | 'completed'
  notes text,                   -- Gio's rough session notes; feeds the AI report draft
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table attendance (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references sessions(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  status text not null default 'unmarked', -- 'present' | 'absent' | 'unmarked'
  created_at timestamptz default now(),
  unique (session_id, student_id)
);

create table session_videos (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references sessions(id) on delete cascade,
  drive_file_id text not null,
  drive_link text not null,     -- shareable preview link — never raw video bytes in the DB
  created_at timestamptz default now(),
  unique (session_id, drive_file_id)
);

-- The lesson plan (curriculum template) for a class — e.g. 24 ordered lessons
-- for RCB. Admin-authored. This is what powers the snake-path journey view:
-- each row is one node on the path.
create table lessons (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references classes(id) on delete cascade,
  sequence_number int not null, -- position on the journey path, 1-indexed
  title text not null,
  description text,
  created_at timestamptz default now(),
  unique (class_id, sequence_number)
);

-- Per-student completion state for each lesson node. This replaces the old
-- flat "credits" ledger — a completed lesson IS the credit, now named and
-- ordered instead of an anonymous count.
create table student_lesson_progress (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  lesson_id uuid not null references lessons(id) on delete cascade,
  status text not null default 'locked', -- 'locked' | 'unlocked' | 'completed'
  session_id uuid references sessions(id), -- which session completed it, if any
  completed_date date,
  notes text,
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  unique (student_id, lesson_id)
);

create table report_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  design_reference text,        -- reference to the Claude Design template asset
  is_default boolean not null default true,
  created_at timestamptz default now()
);

create table reports (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  class_id uuid references classes(id),
  template_id uuid references report_templates(id),
  raw_notes text,                -- Gio's rough notes — input to the AI draft
  ai_draft_text text,            -- Claude API output, editable before export
  final_text text,               -- text actually exported to PDF
  final_pdf_url text,
  generated_date date not null default current_date,
  created_at timestamptz default now()
);

create table student_guardians (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  guardian_id uuid not null references users(id) on delete cascade, -- users.role = 'parent'
  created_at timestamptz default now(),
  unique (student_id, guardian_id)
);

-- ============================================================
-- ARCHITECT NOW, BUILD LATER — Future phases
-- ============================================================
-- Deliberately empty. Every V2 item (academy-wide scheduling, Center Manager/Admin
-- screens, multi-center rollout, multiple report templates) reuses tables already
-- defined above via role/center_id — no speculative tables needed for v1.
-- Payments/CRM are permanently out of KOMS's remit (stay on OClass) — not modeled at all.

-- ============================================================
-- ROW LEVEL SECURITY
-- Non-negotiable: this data includes minors. A parent must never be able to
-- retrieve another family's student data under any query.
-- ============================================================

alter table centers enable row level security;
alter table users enable row level security;
alter table classes enable row level security;
alter table students enable row level security;
alter table enrollments enable row level security;
alter table sessions enable row level security;
alter table attendance enable row level security;
alter table session_videos enable row level security;
alter table report_templates enable row level security;
alter table reports enable row level security;
alter table student_guardians enable row level security;

-- A session log is one retriable database transaction. Without this RPC the
-- handler's session update, attendance upsert, and lesson upsert are separate
-- HTTP requests: a later failure can leave a half-logged session. This is
-- SECURITY INVOKER so every read/write remains under the caller's RLS policies.
create or replace function public.log_session(
  p_session_id uuid,
  p_notes text,
  p_attendance jsonb,
  p_lesson_completions jsonb
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_class_id uuid;
begin
  select s.class_id into v_class_id
  from public.sessions s
  where s.id = p_session_id
    and s.teacher_id = auth.uid()
  for update;

  if not found then
    raise insufficient_privilege using message = 'Not authorized to log this session';
  end if;

  if jsonb_typeof(p_attendance) <> 'array'
     or jsonb_typeof(p_lesson_completions) <> 'array' then
    raise invalid_parameter_value using message = 'Attendance and lesson completions must be arrays';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
    left join public.enrollments e
      on e.student_id = a."studentId" and e.class_id = v_class_id
    where e.student_id is null or a.status not in ('present', 'absent')
  ) or exists (
    select 1
    from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
    group by a."studentId" having count(*) > 1
  ) then
    raise insufficient_privilege using message = 'Attendance contains an invalid or duplicate student';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
    left join public.enrollments e
      on e.student_id = p."studentId" and e.class_id = v_class_id
    left join public.lessons l
      on l.id = p."lessonId" and l.class_id = v_class_id
    where e.student_id is null or l.id is null
  ) or exists (
    select 1
    from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
    group by p."studentId", p."lessonId" having count(*) > 1
  ) then
    raise insufficient_privilege using message = 'Lesson completion contains an invalid or duplicate record';
  end if;

  update public.sessions
  set status = 'completed', notes = p_notes, updated_at = now()
  where id = p_session_id;

  insert into public.attendance (session_id, student_id, status)
  select p_session_id, a."studentId", a.status
  from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
  on conflict (session_id, student_id) do update
    set status = excluded.status;

  insert into public.student_lesson_progress (
    student_id, lesson_id, status, session_id, completed_date, updated_at
  )
  select p."studentId", p."lessonId", 'completed', p_session_id,
    (now() at time zone 'Asia/Jakarta')::date, now()
  from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
  on conflict (student_id, lesson_id) do update set
    status = 'completed',
    session_id = excluded.session_id,
    completed_date = excluded.completed_date,
    updated_at = excluded.updated_at;
end;
$$;

revoke execute on function public.log_session(uuid, text, jsonb, jsonb) from public;
grant execute on function public.log_session(uuid, text, jsonb, jsonb) to authenticated;

-- ------------------------------------------------------------
-- CURRENT-USER HELPERS
-- ------------------------------------------------------------
-- A policy ON users may not read FROM users. While rewriting a query the
-- planner expands the policy, hits the subquery's reference to users, and
-- re-applies the same policy to it — Postgres detects the loop and aborts the
-- whole statement with 42P17 "infinite recursion detected in policy for
-- relation users". It is not a slow query or a subtle wrong answer: every
-- statement touching users fails, including proxy.ts's role lookup, which runs
-- on every authenticated request. The failure also propagates outward, because
-- policies on other tables (students_all_teacher and friends) read from users,
-- so expanding *those* re-enters users' policies and trips the same check.
--
-- security definer breaks the loop: the body runs as the function owner
-- (postgres, when this file is run from the SQL editor), and the owner is not
-- subject to RLS, so no policy is expanded inside it. plpgsql rather than sql
-- is deliberate — the planner inlines trivial sql functions, and an inlined
-- body would be back inside the caller's query tree with RLS applied again.
-- (`set search_path` already blocks inlining on its own; the language choice
-- keeps that from being load-bearing.) Both functions are scoped to
-- auth.uid(), so they expose nothing the caller can't already read from its
-- own row via users_select_own.
create or replace function public.current_user_role()
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  r text;
begin
  select role into r from public.users where id = auth.uid();
  return r;
end;
$$;

create or replace function public.current_user_center()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  c uuid;
begin
  select center_id into c from public.users where id = auth.uid();
  return c;
end;
$$;

revoke execute on function public.current_user_role() from public;
revoke execute on function public.current_user_center() from public;
-- anon is granted too, deliberately. Policies are evaluated for whoever runs
-- the query, so a logged-out request touching report_templates would fail with
-- "permission denied for function" instead of the empty result the app expects.
-- Both functions key on auth.uid(), which is null for anon, so they return null
-- and every policy using them is simply false.
grant execute on function public.current_user_role() to authenticated, anon;
grant execute on function public.current_user_center() to authenticated, anon;

-- Breaks the students <-> student_guardians policy cycle.
--
-- student_guardians_all_teacher used to ask "is this student in my center?" with
-- a subquery on students. But students_select_parent answers itself with a
-- subquery on student_guardians, so each table's policy needed the other's
-- evaluated first and Postgres aborted the statement with 42P17 infinite
-- recursion -- on students, student_guardians, and every parent policy that
-- traverses them (enrollments, sessions, attendance, progress, reports).
--
-- security definer is what breaks it: the lookup inside runs without RLS, so it
-- never re-enters the policy that called it. Returning boolean rather than the
-- student's center_id keeps the promise the helpers above make -- it discloses
-- nothing, it answers the authorization question the caller is already entitled
-- to ask about itself, and it keys on auth.uid() the same way. plpgsql for the
-- same reason as the others: it cannot be inlined, so the search_path pin never
-- becomes load-bearing.
create or replace function public.is_staff_for_student(p_student_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean;
begin
  select exists (
    select 1
    from public.students s
    join public.users u on u.id = auth.uid()
    where s.id = p_student_id
      and u.role in ('teacher','center_manager','admin')
      and s.center_id = u.center_id
  ) into ok;
  return ok;
end;
$$;

revoke execute on function public.is_staff_for_student(uuid) from public;
grant execute on function public.is_staff_for_student(uuid) to authenticated, anon;

-- Breaks the classes <-> enrollments policy cycle, the second of the two.
--
-- enrollments_all_teacher asked "is this class mine?" by reading classes, while
-- classes_select_parent answers itself by reading enrollments -- so each table
-- again needed the other's policy evaluated first, and every query touching
-- either aborted with 42P17. Same shape as the students/student_guardians cycle
-- above, same remedy: move the lookup inside a security definer function, where
-- it runs without RLS and cannot re-enter the policy that called it.
--
-- Returns boolean for the same reason is_staff_for_student does: the caller
-- learns only whether it owns the class, which it is entitled to know, and
-- never reads a row out of classes through this path.
create or replace function public.is_teacher_of_class(p_class_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean;
begin
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id and c.teacher_id = auth.uid()
  ) into ok;
  return ok;
end;
$$;

revoke execute on function public.is_teacher_of_class(uuid) from public;
grant execute on function public.is_teacher_of_class(uuid) to authenticated, anon;

-- users: everyone sees/updates only their own row
create policy "users_select_own" on users for select using (id = auth.uid());

-- WITH CHECK is spelled out deliberately. Postgres reuses the USING expression
-- as WITH CHECK when it is omitted, and "id = auth.uid()" still holds after a
-- row rewrites its OWN role — so the omitted form let any authenticated parent
-- run `update users set role='admin', center_id=<their child's class center>`
-- and inherit every *_admin_manage_center policy below. The anon key is public
-- by design, so that reaches PostgREST directly and never passes a route guard.
-- Column-level immutability is enforced by the trigger underneath; this clause
-- keeps the row-level intent readable at the policy site.
create policy "users_update_own" on users for update
  using (id = auth.uid())
  with check (id = auth.uid());

-- Role and center assignment are not self-service. Blocks only self-edits, so
-- an admin managing OTHER staff via users_admin_manage_center is unaffected,
-- as are service-role operations (auth.uid() is null there).
create or replace function prevent_self_privilege_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() = new.id
     and (new.role is distinct from old.role
          or new.center_id is distinct from old.center_id) then
    raise exception 'role and center_id cannot be changed by the account holder';
  end if;
  return new;
end;
$$;

-- create trigger has no "or replace"; the drop keeps a re-run of this file from
-- failing halfway, which matters while Step 7 is still being iterated on.
drop trigger if exists users_block_self_escalation on users;
create trigger users_block_self_escalation
  before update on users
  for each row execute function prevent_self_privilege_escalation();

-- centers: staff can see their own center
create policy "centers_select_staff" on centers for select using (
  id in (select center_id from users where id = auth.uid())
);

-- classes: teacher owns their classes; parent sees classes their child is enrolled in
-- WITH CHECK also pins center_id: with the inherited form a teacher could move
-- one of their own classes into another center, where that center's admin
-- policies would pick it up. Harmless in single-center v1, wrong the moment a
-- second center exists.
create policy "classes_all_teacher" on classes for all
  using (teacher_id = auth.uid())
  with check (
    teacher_id = auth.uid()
    and center_id in (select center_id from users where id = auth.uid())
  );
create policy "classes_select_parent" on classes for select using (
  id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- students: teacher manages students in their center; parent sees only their linked child
create policy "students_all_teacher" on students for all using (
  center_id in (select center_id from users where id = auth.uid() and role in ('teacher','center_manager','admin'))
);
create policy "students_select_parent" on students for select using (
  id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- enrollments: teacher manages enrollments for their own classes; parent sees their child's
create policy "enrollments_all_teacher" on enrollments for all using (
  public.is_teacher_of_class(class_id)
);
create policy "enrollments_select_parent" on enrollments for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- sessions: teacher manages their own sessions; parent sees sessions for their child's classes
create policy "sessions_all_teacher" on sessions for all using (teacher_id = auth.uid());
create policy "sessions_select_parent" on sessions for select using (
  class_id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- attendance: teacher manages for their sessions; parent sees only their own child's rows
-- Both halves are required. Gating on session_id alone lets a teacher who owns
-- the session write an attendance row for ANY student in the academy; the
-- enrollment clause pins student_id to the session's own class.
create policy "attendance_all_teacher" on attendance for all using (
  session_id in (select id from sessions where teacher_id = auth.uid())
  and student_id in (
    select e.student_id from enrollments e
    join sessions s on s.class_id = e.class_id
    where s.id = attendance.session_id
  )
);
create policy "attendance_select_parent" on attendance for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- session_videos: teacher manages for their sessions; parent sees videos tied to their child's sessions
create policy "session_videos_all_teacher" on session_videos for all using (
  session_id in (select id from sessions where teacher_id = auth.uid())
);
create policy "session_videos_select_parent" on session_videos for select using (
  session_id in (
    select a.session_id from attendance a
    join student_guardians sg on sg.student_id = a.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- lessons: teacher/admin manage lessons for their own classes; parent/student can view
-- the lesson plan for classes their child is enrolled in (needed to render the journey)
alter table lessons enable row level security;
alter table student_lesson_progress enable row level security;

create policy "lessons_all_teacher" on lessons for all using (
  class_id in (select id from classes where teacher_id = auth.uid())
);
create policy "lessons_select_parent" on lessons for select using (
  class_id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- student_lesson_progress: teacher manages for their students; parent sees only their own child's progress
-- As with attendance: the lesson clause alone would let a teacher mark any
-- student in the academy complete on one of their own lessons. The enrollment
-- clause pins student_id to a class that actually contains that lesson.
create policy "progress_all_teacher" on student_lesson_progress for all using (
  lesson_id in (
    select l.id from lessons l
    join classes c on c.id = l.class_id
    where c.teacher_id = auth.uid()
  )
  and student_id in (
    select e.student_id from enrollments e
    join lessons l on l.class_id = e.class_id
    where l.id = student_lesson_progress.lesson_id
  )
);
create policy "progress_select_parent" on student_lesson_progress for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- reports: teacher manages for their students; parent sees only their own child's reports
create policy "reports_all_teacher" on reports for all using (
  student_id in (
    select e.student_id from enrollments e
    join classes c on c.id = e.class_id
    where c.teacher_id = auth.uid()
  )
);
create policy "reports_select_parent" on reports for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- report_templates: any authenticated staff can read; Gio edits the row directly via
-- the Supabase dashboard in v1 — no in-app editor, per PRD Out of Scope.
-- "auth.uid() is not null" was every authenticated user, parents included —
-- the name said staff and the expression said anyone. Nothing in the parent
-- portal reads this table (only the two staff report pages do), so the narrow
-- form is what the app actually needs.
create policy "report_templates_select_staff" on report_templates for select using (
  (select public.current_user_role()) in ('teacher','center_manager','admin')
);

-- student_guardians: teacher creates links when adding a student's parent; parent sees only their own links
-- The role filter matches students_all_teacher above and is load-bearing: without
-- it, any user row whose center_id happens to be set — including a parent's —
-- would get ALL (insert/update/delete) on guardian links, letting them attach
-- themselves to another family's child and inherit every parent policy that
-- traverses student_guardians. The users_parent_has_no_center constraint closes
-- the same hole from the other side; both stay.
-- The role filter lives inside is_staff_for_student() now, but it is still
-- load-bearing for exactly the reason described above.
create policy "student_guardians_all_teacher" on student_guardians for all using (
  public.is_staff_for_student(student_id)
);
create policy "student_guardians_select_own" on student_guardians for select using (guardian_id = auth.uid());

-- ============================================================
-- ADMIN OVERRIDE POLICIES
-- role = 'admin' gets full access across the whole center — not just their
-- own classes/sessions. This is what powers Manage Teachers and Academy
-- Schedule. Scoped to center_id, not global, so it stays multi-tenant-safe
-- as more centers come online later.
-- ============================================================

-- Reads the caller's own role/center through the security definer helpers
-- rather than a subquery on users — see the CURRENT-USER HELPERS note above.
-- Each call is wrapped in (select ...) so the planner evaluates it once as an
-- InitPlan instead of once per candidate row.
-- WITH CHECK is spelled out for the same reason it is on users_update_own: the
-- inherited form would be identical here, but an admin editing staff is
-- exactly the path where an accidental widening would be worst.
-- center_manager is deliberately absent from the managed set, matching the
-- pre-existing policy — v1 has no such account, and adding one to the list is
-- a privilege decision, not a bug fix.
create policy "users_admin_manage_center" on users for all
  using (
    (select public.current_user_role()) = 'admin'
    and role in ('teacher','admin')
    and center_id = (select public.current_user_center())
  )
  with check (
    (select public.current_user_role()) = 'admin'
    and role in ('teacher','admin')
    and center_id = (select public.current_user_center())
  );

create policy "classes_admin_manage_center" on classes for all using (
  center_id in (select center_id from users where id = auth.uid() and role = 'admin')
);

create policy "sessions_admin_manage_center" on sessions for all using (
  class_id in (
    select id from classes where center_id in (
      select center_id from users where id = auth.uid() and role = 'admin'
    )
  )
);

create policy "lessons_admin_manage_center" on lessons for all using (
  class_id in (
    select id from classes where center_id in (
      select center_id from users where id = auth.uid() and role = 'admin'
    )
  )
);

-- Report publication boundary (also supplied as a forward migration).
-- Apply once to the existing KodeHub schema. Existing reports stay private.
begin;

alter table public.reports add column pdf_storage_path text;
drop policy if exists "reports_select_parent" on public.reports;

-- Stable class scope, not merely another class that happens to share a student.
create or replace function public.can_manage_report(p_student uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.users u
    join public.classes c on c.id = p_class and c.center_id = u.center_id
    join public.students s on s.id = p_student and s.center_id = c.center_id
    where u.id = auth.uid() and
      (u.role = 'admin' or (u.role = 'teacher' and c.teacher_id = u.id))
  );
$$;
revoke all on function public.can_manage_report(uuid, uuid) from public, anon;
grant execute on function public.can_manage_report(uuid, uuid) to authenticated;

drop policy "reports_all_teacher" on public.reports;
create policy "reports_manage_staff" on public.reports for all to authenticated
  using (public.can_manage_report(student_id, class_id))
  with check (
    public.can_manage_report(student_id, class_id)
    and exists (select 1 from public.enrollments e
      where e.student_id = reports.student_id and e.class_id = reports.class_id)
  );

create table public.published_reports (
  id uuid primary key default gen_random_uuid(),
  report_id uuid not null unique references public.reports(id),
  student_id uuid not null references public.students(id),
  class_id uuid not null references public.classes(id),
  final_text text not null check (length(trim(final_text)) > 0),
  generated_date date not null,
  pdf_storage_path text not null,
  published_by uuid not null references public.users(id),
  published_at timestamptz not null default now(),
  withdrawn_at timestamptz
);
alter table public.published_reports enable row level security;
grant select on public.published_reports to authenticated;
create policy "published_reports_staff_read" on public.published_reports
  for select to authenticated using (public.can_manage_report(student_id, class_id));
create policy "published_reports_family_read" on public.published_reports
  for select to authenticated using (
    withdrawn_at is null and exists (
      select 1 from public.student_guardians g
      where g.student_id = published_reports.student_id and g.guardian_id = auth.uid()
    )
  );

-- No client INSERT/UPDATE/DELETE policy. Only these narrowly scoped RPCs write.
create or replace function public.publish_report(p_report_id uuid)
returns uuid language plpgsql security definer set search_path = public
as $$
declare r public.reports; publication_id uuid;
begin
  select * into r from public.reports where id = p_report_id for update;
  if not found or not public.can_manage_report(r.student_id, r.class_id) then
    raise exception 'Report not found' using errcode = '42501';
  end if;
  if r.final_text is null or length(trim(r.final_text)) = 0
    or r.pdf_storage_path is distinct from r.student_id::text || '/' || r.id::text || '.pdf' then
    raise exception 'Export a PDF before publishing' using errcode = '23514';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'reports' and name = r.pdf_storage_path) then
    raise exception 'Export a PDF before publishing' using errcode = '23514';
  end if;
  insert into public.published_reports
    (report_id, student_id, class_id, final_text, generated_date, pdf_storage_path, published_by)
  values (r.id, r.student_id, r.class_id, r.final_text, r.generated_date, r.pdf_storage_path, auth.uid())
  on conflict (report_id) do nothing returning id into publication_id;
  if publication_id is null then
    select id into publication_id from public.published_reports where report_id = r.id;
  end if;
  -- A retry never reopens a withdrawn snapshot. Export a new version to republish.
  return publication_id;
end;
$$;

create or replace function public.withdraw_report(p_publication_id uuid)
returns void language plpgsql security definer set search_path = public
as $$
declare r public.published_reports;
begin
  select * into r from public.published_reports where id = p_publication_id for update;
  if not found or not public.can_manage_report(r.student_id, r.class_id) then
    raise exception 'Report not found' using errcode = '42501';
  end if;
  update public.published_reports set withdrawn_at = coalesce(withdrawn_at, now())
    where id = r.id;
end;
$$;
revoke all on function public.publish_report(uuid) from public, anon;
revoke all on function public.withdraw_report(uuid) from public, anon;
grant execute on function public.publish_report(uuid) to authenticated;
grant execute on function public.withdraw_report(uuid) to authenticated;

commit;

-- Credit ledger boundary (also supplied as a forward migration).
-- Apply once, after report publications. Existing sessions are billing-exempt.
begin;
alter table public.sessions add column credit_billable boolean not null default false;
alter table public.sessions alter column credit_billable set default true;
alter table public.sessions add column revision integer not null default 0 check (revision >= 0);

create table public.credit_accounts (
  student_id uuid primary key references public.students(id),
  balance integer not null default 0 check (balance >= 0),
  revision integer not null default 0 check (revision >= 0)
);
create table public.credit_operations (
  actor_id uuid not null references public.users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);
create table public.credit_entries (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.credit_accounts(student_id),
  amount integer not null check (amount <> 0),
  kind text not null check (kind in ('top_up','adjustment','attendance_charge','attendance_refund')),
  reason text not null check (length(trim(reason)) between 1 and 500),
  actor_id uuid not null references public.users(id),
  request_id uuid not null,
  session_id uuid references public.sessions(id),
  effective_date date not null,
  recorded_at timestamptz not null default now(),
  unique (actor_id, request_id, student_id),
  foreign key (actor_id, request_id) references public.credit_operations(actor_id, request_id) deferrable initially deferred,
  check ((kind = 'top_up' and amount > 0 and session_id is null)
    or (kind = 'adjustment' and session_id is null)
    or (kind = 'attendance_charge' and amount = -1 and session_id is not null)
    or (kind = 'attendance_refund' and amount = 1 and session_id is not null))
);
create table public.session_credit_state (
  session_id uuid not null references public.sessions(id),
  student_id uuid not null references public.credit_accounts(student_id),
  charged boolean not null,
  primary key (session_id, student_id)
);
create index credit_entries_student_history on public.credit_entries(student_id, recorded_at desc, id desc);
insert into public.credit_accounts(student_id) select id from public.students;

create or replace function public.can_read_credits(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.users u join public.students s on s.id = p_student
    where u.id = auth.uid() and (
      (u.role = 'admin' and u.center_id = s.center_id)
      or (u.role = 'teacher' and u.center_id = s.center_id and exists (
        select 1 from public.enrollments e join public.classes c on c.id = e.class_id
        where e.student_id = s.id and c.teacher_id = u.id and c.center_id = u.center_id))
      or (u.role = 'parent' and exists (select 1 from public.student_guardians g
        where g.student_id = s.id and g.guardian_id = u.id))));
$$;
alter table public.credit_accounts enable row level security;
alter table public.credit_entries enable row level security;
alter table public.credit_operations enable row level security;
alter table public.session_credit_state enable row level security;
create policy "credit_accounts_read" on public.credit_accounts for select to authenticated
  using (public.can_read_credits(student_id));
create policy "credit_entries_read" on public.credit_entries for select to authenticated
  using (public.can_read_credits(student_id));
create policy "credit_operations_private" on public.credit_operations for select using (false);
create policy "session_credit_state_private" on public.session_credit_state for select using (false);
grant select on public.credit_accounts, public.credit_entries to authenticated;

-- Direct attendance writes and billing-flag edits would bypass the ledger.
-- Definer RPCs execute as the schema owner; ordinary PostgREST users do not.
create or replace function public.guard_credit_writes()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_table_name = 'attendance' then
      raise exception 'Use the session logging RPC' using errcode = '42501';
    elsif tg_op = 'INSERT' then
      if not new.credit_billable or new.revision <> 0 or new.status <> 'scheduled' then
        raise exception 'Invalid new session billing state' using errcode = '42501';
      end if;
    elsif new.credit_billable is distinct from old.credit_billable
      or new.revision is distinct from old.revision or new.class_id is distinct from old.class_id
      or new.status is distinct from old.status or new.notes is distinct from old.notes then
      raise exception 'Use the session logging RPC' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
create trigger attendance_credit_guard before insert or update or delete on public.attendance
  for each row execute function public.guard_credit_writes();
create trigger session_credit_guard before insert or update on public.sessions
  for each row execute function public.guard_credit_writes();

create or replace function public.adjust_credits(p_student uuid, p_amount integer, p_kind text, p_reason text, p_request uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_payload jsonb; v_receipt public.credit_operations; v_balance integer; v_result jsonb;
begin
  if not exists (select 1 from public.users u join public.students s on s.center_id = u.center_id
      where u.id = auth.uid() and u.role = 'admin' and s.id = p_student) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_request is null or p_amount is null or p_amount = 0 or abs(p_amount::bigint) > 10000
    or p_kind is null or p_kind not in ('top_up','adjustment') or (p_kind = 'top_up' and p_amount < 0)
    or p_reason is null or length(trim(p_reason)) not between 1 and 500 then
    raise exception 'Invalid credit adjustment' using errcode = '22023';
  end if;
  v_payload := jsonb_build_object('operation','adjust','student',p_student,'amount',p_amount,'kind',p_kind,'reason',trim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || p_request::text, 0));
  select * into v_receipt from public.credit_operations where actor_id = auth.uid() and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then raise exception 'Request ID already used for different data' using errcode = 'P0002'; end if;
    return v_receipt.result;
  end if;
  insert into public.credit_accounts(student_id) values (p_student) on conflict do nothing;
  select balance into v_balance from public.credit_accounts where student_id = p_student for update;
  if v_balance::bigint + p_amount < 0 or v_balance::bigint + p_amount > 2147483647 then
    raise exception 'Insufficient credits or balance limit exceeded' using errcode = 'P0001';
  end if;
  update public.credit_accounts set balance = balance + p_amount, revision = revision + 1 where student_id = p_student;
  insert into public.credit_entries(student_id,amount,kind,reason,actor_id,request_id,effective_date)
    values (p_student,p_amount,p_kind,trim(p_reason),auth.uid(),p_request,(now() at time zone 'Asia/Jakarta')::date);
  v_result := jsonb_build_object('balance',v_balance + p_amount);
  insert into public.credit_operations(actor_id,request_id,payload,result) values(auth.uid(),p_request,v_payload,v_result);
  return v_result;
end;
$$;

create or replace function public.log_session_credits(
  p_session_id uuid, p_notes text, p_attendance jsonb, p_lesson_completions jsonb,
  p_request uuid, p_expected_revision integer
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_session public.sessions; v_payload jsonb; v_receipt public.credit_operations;
  a record; v_charged boolean; v_delta integer; v_balance integer; v_result jsonb;
begin
  if auth.uid() is null or p_request is null or p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'Invalid request identity or revision' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || p_request::text, 0));
  select * into v_session from public.sessions where id = p_session_id for update;
  if not found or not exists (select 1 from public.users u join public.classes c on c.center_id = u.center_id
    where u.id = auth.uid() and c.id = v_session.class_id and
      (u.role = 'admin' or (u.role = 'teacher' and c.teacher_id = u.id and v_session.teacher_id = u.id))) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  v_payload := jsonb_build_object('operation','log','session',p_session_id,'notes',p_notes,
    'attendance',p_attendance,'lessons',p_lesson_completions,'revision',p_expected_revision);
  select * into v_receipt from public.credit_operations where actor_id = auth.uid() and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then raise exception 'Request ID already used for different data' using errcode = 'P0002'; end if;
    return v_receipt.result;
  end if;
  if v_session.revision <> p_expected_revision then raise exception 'Session changed. Reload before saving.' using errcode = 'P0002'; end if;
  if jsonb_typeof(p_attendance) is distinct from 'array' or jsonb_typeof(p_lesson_completions) is distinct from 'array'
    or length(coalesce(p_notes,'')) > 10000 then
    raise exception 'Invalid session payload' using errcode = '22023';
  end if;
  if jsonb_array_length(p_attendance) > 500 or jsonb_array_length(p_lesson_completions) > 5000 then
    raise exception 'Session payload too large' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text)
    left join public.students s on s.id = x."studentId"
    join public.classes c on c.id = v_session.class_id
    where s.id is null or s.center_id <> c.center_id or x.status is null or x.status not in ('present','absent','unmarked')
    or (not exists (select 1 from public.enrollments e where e.student_id = x."studentId" and e.class_id = c.id)
      and not (x.status in ('absent','unmarked') and exists (select 1 from public.session_credit_state sc
        where sc.session_id = p_session_id and sc.student_id = x."studentId" and sc.charged))))
    or exists (select 1 from jsonb_to_recordset(p_attendance) as x("studentId" uuid)
      group by x."studentId" having count(*) > 1) then
    raise exception 'Invalid attendance scope' using errcode = '42501';
  end if;
  if exists (select 1 from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
    left join public.enrollments e on e.student_id = x."studentId" and e.class_id = v_session.class_id
    left join public.lessons l on l.id = x."lessonId" and l.class_id = v_session.class_id
    left join public.students s on s.id = x."studentId"
    join public.classes c on c.id = v_session.class_id
    where e.id is null or l.id is null or s.center_id <> c.center_id)
    or exists (select 1 from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
      group by x."studentId", x."lessonId" having count(*) > 1) then
    raise exception 'Invalid lesson scope' using errcode = '42501';
  end if;
  if v_session.credit_billable then
    -- Stable ordering prevents two class logs from locking shared learners in reverse order.
    for a in select * from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text) order by x."studentId" loop
      insert into public.credit_accounts(student_id) values(a."studentId") on conflict do nothing;
      select balance into v_balance from public.credit_accounts where student_id = a."studentId" for update;
      select charged into v_charged from public.session_credit_state where session_id = p_session_id and student_id = a."studentId";
      v_delta := coalesce(v_charged,false)::integer - (a.status = 'present')::integer;
      if v_balance::bigint + v_delta < 0 or v_balance::bigint + v_delta > 2147483647 then
        raise exception 'Credit balance would be out of range' using errcode = 'P0001';
      end if;
      if v_delta <> 0 then
        update public.credit_accounts set balance = balance + v_delta, revision = revision + 1 where student_id = a."studentId";
        insert into public.credit_entries(student_id,amount,kind,reason,actor_id,request_id,session_id,effective_date)
          values(a."studentId",v_delta,case when v_delta < 0 then 'attendance_charge' else 'attendance_refund' end,
            case when v_delta < 0 then 'Session attendance' else 'Attendance correction' end,
            auth.uid(),p_request,p_session_id,v_session.session_date);
      end if;
      insert into public.session_credit_state(session_id,student_id,charged) values(p_session_id,a."studentId",a.status = 'present')
        on conflict(session_id,student_id) do update set charged = excluded.charged;
    end loop;
  end if;
  update public.sessions set status = 'completed', notes = p_notes, revision = revision + 1, updated_at = now() where id = p_session_id;
  insert into public.attendance(session_id,student_id,status)
    select p_session_id,x."studentId",x.status from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text)
    on conflict(session_id,student_id) do update set status = excluded.status;
  insert into public.student_lesson_progress(student_id,lesson_id,status,session_id,completed_date,updated_at)
    select x."studentId",x."lessonId",'completed',p_session_id,(now() at time zone 'Asia/Jakarta')::date,now()
    from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
    on conflict(student_id,lesson_id) do update set status = 'completed',session_id = excluded.session_id,
      completed_date = excluded.completed_date,updated_at = excluded.updated_at;
  v_result := jsonb_build_object('revision',v_session.revision + 1);
  insert into public.credit_operations(actor_id,request_id,payload,result) values(auth.uid(),p_request,v_payload,v_result);
  return v_result;
end;
$$;

revoke all on function public.log_session(uuid,text,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.can_read_credits(uuid) from public,anon;
revoke all on function public.adjust_credits(uuid,integer,text,text,uuid) from public,anon;
revoke all on function public.log_session_credits(uuid,text,jsonb,jsonb,uuid,integer) from public,anon;
grant execute on function public.can_read_credits(uuid) to authenticated;
grant execute on function public.adjust_credits(uuid,integer,text,text,uuid) to authenticated;
grant execute on function public.log_session_credits(uuid,text,jsonb,jsonb,uuid,integer) to authenticated;
commit;

-- Reusable course library (also supplied as a forward migration).
begin;

-- Reusable courses do not change existing class lessons or learner progress.
alter table users add constraint users_id_center_unique unique (id, center_id);
create table courses (
  id uuid primary key,
  center_id uuid not null references centers(id),
  owner_id uuid not null,
  title text not null check (length(btrim(title)) between 1 and 200),
  category text not null check (length(category) <= 100),
  age_range text not null check (length(age_range) <= 100),
  level text not null check (length(level) <= 100),
  description text not null check (length(description) <= 10000),
  prerequisites text not null check (length(prerequisites) <= 10000),
  revision integer not null default 1 check (revision > 0),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (owner_id, center_id) references users(id, center_id)
);
create index courses_center_id_idx on courses(center_id, id);

create table course_lessons (
  id uuid primary key,
  course_id uuid not null references courses(id),
  sequence integer not null check (sequence between 1 and 10000),
  title text not null check (length(btrim(title)) between 1 and 200),
  minutes integer not null check (minutes between 1 and 1440),
  objective text not null check (length(objective) <= 10000),
  materials text not null check (length(materials) <= 10000),
  steps text not null check (length(steps) <= 20000),
  evidence text not null check (length(evidence) <= 10000),
  revision integer not null default 1 check (revision > 0),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (course_id, sequence)
);

create table course_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);
alter table courses enable row level security;
alter table course_lessons enable row level security;
alter table course_write_receipts enable row level security;
create policy "courses_read_staff" on courses for select to authenticated
  using (center_id = public.current_user_center() and public.current_user_role() in ('teacher','admin'));
create policy "course_lessons_read_staff" on course_lessons for select to authenticated
  using (exists (select 1 from courses c where c.id = course_id));
create policy "course_receipts_private" on course_write_receipts for select to authenticated using (false);
-- No client mutation policies; receipts remain private to the RPC.

-- Full content replacement with optimistic revisions. Revision 0 creates a row.
-- The course lock also serializes lesson edits against course archiving.
create function public.save_course_content(
  p_course uuid, p_lesson uuid, p_expected_revision integer,
  p_request uuid, p_content jsonb
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_center uuid;
  v_course courses%rowtype;
  v_lesson course_lessons%rowtype;
  v_receipt course_write_receipts%rowtype;
  v_payload jsonb;
  v_result jsonb;
  v_fields text[];
  v_key text;
  v_revision integer;
  v_archived timestamptz;
begin
  select role, center_id into v_role, v_center from users where id = v_actor;
  if v_actor is null or v_center is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_course is null or p_request is null or p_expected_revision is null or p_expected_revision < 0
     or p_content is null or jsonb_typeof(p_content) <> 'object' then
    raise exception 'Invalid content' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('course-request:' || v_actor::text || ':' || p_request::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('course:' || p_course::text, 0));
  select * into v_course from courses where id = p_course for update;
  if v_course.id is not null and (v_course.center_id <> v_center or (v_role <> 'admin' and v_course.owner_id <> v_actor)) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if v_course.id is null and (p_lesson is not null or p_expected_revision <> 0) then
    raise exception 'Not found' using errcode = '42501';
  end if;
  v_payload := jsonb_build_object('course',p_course,'lesson',p_lesson,'revision',p_expected_revision,'content',p_content);
  select * into v_receipt from course_write_receipts where actor_id = v_actor and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then
      raise exception 'Request reused' using errcode = 'P0002';
    end if;
    return v_receipt.result;
  end if;
  v_fields := case when p_lesson is null
    then array['title','category','age_range','level','description','prerequisites']
    else array['title','objective','materials','steps','evidence'] end;
  foreach v_key in array v_fields loop
    if jsonb_typeof(p_content->v_key) is distinct from 'string' then
      raise exception 'Invalid text field' using errcode = '22023';
    end if;
  end loop;
  v_fields := v_fields || array['archived'];
  if p_lesson is not null then
    v_fields := v_fields || array['sequence','minutes'];
    if jsonb_typeof(p_content->'sequence') is distinct from 'number'
       or jsonb_typeof(p_content->'minutes') is distinct from 'number'
       or (p_content->>'sequence') !~ '^[0-9]+$' or (p_content->>'minutes') !~ '^[0-9]+$' then
      raise exception 'Invalid lesson numbers' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(p_content->'archived') is distinct from 'boolean'
     or exists (select 1 from jsonb_object_keys(p_content) k where not (k = any(v_fields))) then
    raise exception 'Invalid fields' using errcode = '22023';
  end if;
  if p_lesson is null then
    v_revision := coalesce(v_course.revision, 0);
    v_archived := v_course.archived_at;
  else
    if v_course.archived_at is not null then
      raise exception 'Restore course before editing lessons' using errcode = 'P0002';
    end if;
    -- Also lock absent lesson IDs: two courses must not concurrently create the
    -- same lesson ID and reach an UPSERT against another course's content.
    perform pg_advisory_xact_lock(hashtextextended('course-lesson:' || p_lesson::text, 0));
    -- Also lock absent lesson IDs: two courses must not concurrently create the
    -- same lesson ID and reach an UPSERT against another course's content.
    perform pg_advisory_xact_lock(hashtextextended('course-lesson:' || p_lesson::text, 0));
    select * into v_lesson from course_lessons where id = p_lesson for update;
    if v_lesson.id is not null and v_lesson.course_id <> p_course then
      raise exception 'Not authorized' using errcode = '42501';
    end if;
    v_revision := coalesce(v_lesson.revision, 0);
    v_archived := v_lesson.archived_at;
  end if;
  if v_revision <> p_expected_revision then
    raise exception 'Stale revision' using errcode = 'P0002';
  end if;
  v_archived := case when (p_content->>'archived')::boolean then coalesce(v_archived, now()) else null end;
  if p_lesson is null then
    insert into courses(id,center_id,owner_id,title,category,age_range,level,description,prerequisites,archived_at)
    values(p_course,v_center,v_actor,p_content->>'title',p_content->>'category',p_content->>'age_range',
      p_content->>'level',p_content->>'description',p_content->>'prerequisites',v_archived)
    on conflict(id) do update set title=excluded.title, category=excluded.category, age_range=excluded.age_range,
      level=excluded.level, description=excluded.description, prerequisites=excluded.prerequisites,
      archived_at=excluded.archived_at, revision=courses.revision+1, updated_at=now();
  else
    insert into course_lessons(id,course_id,sequence,title,minutes,objective,materials,steps,evidence,archived_at)
    values(p_lesson,p_course,(p_content->>'sequence')::integer,p_content->>'title',(p_content->>'minutes')::integer,
      p_content->>'objective',p_content->>'materials',p_content->>'steps',p_content->>'evidence',v_archived)
    on conflict(id) do update set sequence=excluded.sequence,title=excluded.title,minutes=excluded.minutes,
      objective=excluded.objective,materials=excluded.materials,steps=excluded.steps,evidence=excluded.evidence,
      archived_at=excluded.archived_at, revision=course_lessons.revision+1,updated_at=now();
  end if;
  v_result := jsonb_build_object('id',coalesce(p_lesson,p_course),'revision',v_revision+1);
  insert into course_write_receipts(actor_id,request_id,payload,result) values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) from public,anon;
grant execute on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) to authenticated;
grant select on courses,course_lessons to authenticated;
-- TRUNCATE bypasses RLS; Supabase bootstrap privileges must not permit it.
revoke truncate on courses,course_lessons,course_write_receipts from public,anon,authenticated;
commit;
